<div class="student-appbar"><a class="student-back" href="/aluno/ferramentas.php">← Ferramentas</a></div><p class="student-kicker">Laboratório</p><h1 class="student-title">Preparo de soluções</h1><p class="student-lead">Escolha o preparo e informe o volume desejado. As quantidades são redimensionadas automaticamente.</p><section class="student-tool-workspace" data-solution-tool><div class="student-form-grid"><label class="form-field">Preparo<select data-solution-select><?php foreach($formulas as $key=>$formula):?><option value="<?=h($key)?>"><?=h((string)$formula['label'])?></option><?php endforeach;?></select></label><label class="form-field">Volume desejado (ml)<input type="number" min="1" step="1" value="250" data-solution-volume></label></div><?php foreach($formulas as $key=>$formula):?><div class="student-solution-formula" data-solution-formula="<?=h($key)?>" data-base-volume="<?=h((string)$formula['base_volume'])?>"<?=$key!==array_key_first($formulas)?' hidden':''?>><h2><?=h((string)$formula['label'])?></h2><?php if(!empty($formula['fresh'])):?><span class="student-status">Uso imediato</span><?php endif;?><div class="student-solution-ingredients"><?php foreach($formula['ingredients'] as $ingredient):?><div><span><?=h((string)$ingredient['name'])?></span><strong data-solution-amount="<?=h((string)$ingredient['amount'])?>" data-unit="<?=h((string)$ingredient['unit'])?>"><?=h((string)$ingredient['amount'].' '.$ingredient['unit'])?></strong></div><?php endforeach;?></div></div><?php endforeach;?></section><?php student_shell_end();